pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        vm.warp(3);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "first fallback failed");

        uint refVal = c.pastBlockTime();
        assertTrue(refVal == 3, "pastBlockTime should be 3 for reference");
    }
}
